//
// A QR as GoTrue v2.197.0 sends it on an enrol: raw SVG written by SVGo
// (`goqrsvg`, block size 3), every module a square, light ones included,
// which is why it runs to hundreds of thousands of characters.

const HEAD =
  '<?xml version="1.0"?>\n<!-- Generated by SVGo -->\n<svg width="219" height="219"\n' +
  '     xmlns="http://www.w3.org/2000/svg" \n     xmlns:xlink="http://www.w3.org/1999/xlink">\n';
const TAIL = '</svg>\n';

function module(at: number): string {
  const fill = at % 3 === 0 ? '0,0,0' : '255,255,255';
  return `<rect x="${(at % 73) * 3}" y="${Math.floor(at / 73) * 3}" width="3" height="3" style="fill:rgb(${fill})" />\n`;
}

/**
 * GoTrue's raw SVG QR, exactly `characters` long; `mark` names whose it is.
 * Only whole modules are written, and whitespace between the last of them and
 * the closing tag makes up the length, so it is well-formed SVG at any length.
 */
export function gotrueQrSvg(characters: number, mark = ''): string {
  const head = mark === '' ? HEAD : `${HEAD}<!-- ${mark} -->\n`;
  const modules: string[] = [];
  let length = head.length + TAIL.length;
  for (let at = 0; ; at += 1) {
    const next = module(at);
    if (length + next.length > characters) break;
    modules.push(next);
    length += next.length;
  }
  if (length > characters) throw new Error(`a QR cannot be ${characters} characters long`);
  return `${head}${modules.join('')}${' '.repeat(characters - length)}${TAIL}`;
}
